from abc import ABC
from itertools import cycle, islice
from typing import List, Optional, Union

from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import CSV4AllTest, test_logger, method_decorator
from taf.rfrl.csv4all.resources.test_cases.exceptions import TestPreconditionFailed
from taf.rfrl.csv4all.resources.utilities.utilities import set_robot_test_variable


class ModuleTest(CSV4AllTest, ABC):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method, detailed_console_log,
                         collect_passed_logs)
        self.module_type = None

    def test_setup(self):
        super().test_setup()
        self.set_modules_eligible_for_test()

    @method_decorator()
    def set_modules_eligible_for_test(self):
        test_logger("Setting modules eligible for test")
        nodes_without_eligible_modules = []
        for node in self.test_nodes:
            modules = {}
            if self.module_type == "radio":
                modules = node.radioModules
            elif self.module_type == "baseband":
                modules = node.basebandModules
            modules_for_test = [module for module, module_inf in modules.items()
                                if module_inf.get("Eligible For Reset") is True]
            if hasattr(node, "modules_for_test"):
                test_logger(f"Modules for test provided by user: {node.modules_for_test}")
                modules_for_test = [module for module in modules_for_test if module in node.modules_for_test]
            test_logger(f"Eligible modules for node {node.node_alias} {modules_for_test}")
            node.modules_for_test = iter(islice(cycle(modules_for_test), 2*self.iterations_per_node))
            if not modules_for_test:
                test_logger(f"Node {node.node_alias} doesn't have any {self.module_type} modules,"
                            f" which are eligible for test. This node will be removed from test scope",
                            log_level="WARN")
                nodes_without_eligible_modules.append(node)

        for node in nodes_without_eligible_modules:
            self.test_nodes.remove(node)
        if not self.test_nodes:
            raise Exception("There is no Node with eligible modules for test!!!")

    @method_decorator()
    def set_l3_all_dependent_cells(self, node, module):
        if self.module_type == "radio":
            self.l3_call_dependent_cells = [cell for cell in node.radioModules.get(module).get("Mapped Cells")]
        elif self.module_type == "baseband":
            self.l3_call_dependent_cells = [cell for cell in node.basebandModules.get(module).get("Mapped Cells")]

    def add_faults_on_shared_rmod(self, node, rmod: str, fault_ids: Union[list, str]):
        if not isinstance(fault_ids, list):
            fault_ids = [fault_ids]
        if node.radioModules[rmod].get("Eligible For Reset"):
            for fault_id in self.allowed_faults_on_radio_master:
                node.add_test_specific_alarm(fault_id, unit_path=rmod)
            self.add_allowed_fault_alarm_for_slave(node, fault_ids=self.allowed_faults_on_radio_slave,
                                                   rmod_sn=node.radioModules[rmod]["Serial Number"])
        self.add_allowed_fault_alarm_for_slave(node, fault_ids=fault_ids,
                                               rmod_sn=node.radioModules[rmod]["Serial Number"])

    def run_test_precondition(self):
        try:
            super().run_test_precondition()
        except TestPreconditionFailed as e:
            for node in self.test_nodes:
                next(node.modules_for_test)
            raise e
